"""Pass 1: facts about ONE Python file (ADR-0003).

Pure function of (path, source): it never reads other files, so its result can be cached by
content hash. Everything that needs other files (resolving names, types, calls) is pass 2.

Facts are plain JSON-serialisable dicts:
  imports    [{alias, target, line}]              alias bound in this module -> dotted target
  classes    [{name, line, end_line, bases, decorators, doc, attr_types}]
  functions  [{qualname, name, cls, line, end_line, params, returns, is_async, decorators,
               doc, calls, vars, sql}]          (+ one "<module>" pseudo-function for top-level code)
  module_vars {name: type_spec}                    type_spec = {"ann": str} | {"call": chain}
  routes     [{verb, path, function, receiver, line}]
A call "chain" is the callee written as tokens: `a.b().c` -> ["a", "b", "()", "c"].
"""

from __future__ import annotations

import ast
import re

EXTRACTOR_VERSION = "3"  # bump whenever the facts change shape: invalidates cached results (ADR-0003)
SCRIPT = "<module>"
HTTP_VERBS = {"get", "post", "put", "delete", "patch", "head", "options"}

# ---------------------------------------------------------------- module naming


def module_name(path: str) -> str:
    """'src/shop/orders.py' -> 'src.shop.orders'; '__init__.py' names the package."""
    parts = path[:-3].split("/") if path.endswith(".py") else path.split("/")
    if parts[-1] == "__init__":
        parts = parts[:-1]
    return ".".join(parts)


def is_test_path(path: str) -> bool:
    name = path.rsplit("/", 1)[-1]
    return (
        path.startswith("tests/")
        or "/tests/" in path
        or name.startswith("test_")
        or name.endswith("_test.py")
        or name == "conftest.py"
    )


# ---------------------------------------------------------------- SQL table references (certainty: pattern)

_NAME = r"([A-Za-z_][\w.]*)\b"
_SQL_HINT = re.compile(
    r"\b(SELECT|INSERT|CREATE|UPDATE|DELETE|DROP|ALTER)\b"
)  # uppercase SQL only (documented limit)
_READ = re.compile(r"\b(?:FROM|JOIN)\s+" + _NAME + r"(?!\s*\()")
_WRITES = [
    re.compile(r"\bINSERT\s+INTO\s+" + _NAME),
    re.compile(
        r"\bCREATE\s+(?:OR\s+REPLACE\s+)?(?:TEMP(?:ORARY)?\s+)?TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?" + _NAME
    ),
    re.compile(r"\bCREATE\s+(?:UNIQUE\s+)?INDEX\s+(?:IF\s+NOT\s+EXISTS\s+)?\w+\s+ON\s+" + _NAME),
    re.compile(r"\bDROP\s+TABLE\s+(?:IF\s+EXISTS\s+)?" + _NAME),
    re.compile(r"\bALTER\s+TABLE\s+" + _NAME),
    re.compile(r"\bUPDATE\s+" + _NAME + r"\s+SET\b"),
    re.compile(r"\bDELETE\s+FROM\s+" + _NAME),
]
_CTE = re.compile(r"(?:\bWITH\s+(?:RECURSIVE\s+)?|,\s*)([A-Za-z_]\w*)\s+AS\s*\(")
_NOT_TABLES = {"SELECT", "VALUES", "LATERAL", "UNNEST", "TABLE"}


def sql_tables(text: str) -> list[tuple[str, str]]:
    """[(table, 'reads'|'writes')] found in one SQL string."""
    if not _SQL_HINT.search(text):
        return []
    ctes = {m.group(1).lower() for m in _CTE.finditer(text)}
    found: list[tuple[str, str]] = []
    for rx in _WRITES:
        found += [(m.group(1), "writes") for m in rx.finditer(text)]
    for m in _READ.finditer(text):
        if text[: m.start()].rstrip().upper().endswith("DELETE"):
            continue  # DELETE FROM x is a write, already counted
        found.append((m.group(1), "reads"))
    out = []
    for name, op in found:
        name = name.strip('"').lower()
        if name in ctes or name.upper() in _NOT_TABLES:
            continue
        out.append((name, op))
    return out


# ---------------------------------------------------------------- helpers


def chain_of(expr: ast.AST) -> list[str] | None:
    """Callee expression as tokens, or None when it isn't a simple name/attribute/call chain."""
    if isinstance(expr, ast.Name):
        return [expr.id]
    if isinstance(expr, ast.Attribute):
        base = chain_of(expr.value)
        return base + [expr.attr] if base is not None else None
    if isinstance(expr, ast.Call):
        base = chain_of(expr.func)
        return base + ["()"] if base is not None else None
    return None


def _doc(node: ast.AST) -> str | None:
    d = ast.get_docstring(node)  # type: ignore[arg-type]
    return d.strip().splitlines()[0] if d else None


def _strings(nodes: list[ast.stmt]):
    """String constants and f-strings inside statements (f-string holes become a space)."""
    for stmt in nodes:
        for n in ast.walk(stmt):
            if isinstance(n, ast.JoinedStr):
                parts = [
                    v.value if isinstance(v, ast.Constant) and isinstance(v.value, str) else " "
                    for v in n.values
                ]
                yield "".join(parts), n.lineno
            elif isinstance(n, ast.Constant) and isinstance(n.value, str):
                yield n.value, n.lineno


def _without_docstring(body: list[ast.stmt]) -> list[ast.stmt]:
    first = body[0] if body else None
    if (
        isinstance(first, ast.Expr)
        and isinstance(first.value, ast.Constant)
        and isinstance(first.value.value, str)
    ):
        return body[1:]
    return body


_LITERALS = (ast.Dict, ast.List, ast.Set, ast.Tuple, ast.JoinedStr, ast.ListComp, ast.DictComp, ast.SetComp)


def _type_spec(value: ast.AST | None, annotation: ast.AST | None) -> dict | None:
    if annotation is not None:
        return {"ann": ast.unparse(annotation)}
    if isinstance(value, _LITERALS) or (isinstance(value, ast.Constant) and value.value is not None):
        return {"builtin": True}  # [], {}, "", 1, f"…": a builtin object
    if isinstance(value, ast.Call):
        ch = chain_of(value.func)
        if ch:
            return {"call": ch}
    return None


def _body_facts(body: list[ast.stmt]) -> dict:
    """Calls, local variable types, SQL tables, HTTP requests and nested definitions found in a list
    of statements. Nested function/class bodies are included: their effects belong to the enclosing code."""
    calls, vars_, sql, http, local_defs = [], {}, [], [], []
    for stmt in body:
        for n in ast.walk(stmt):
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                local_defs.append(n.name)
            if isinstance(n, ast.Call):
                ch = chain_of(n.func)
                if ch:
                    calls.append({"chain": ch, "line": n.lineno})
                req = _http_request(n)
                if req:
                    http.append(req)
            elif isinstance(n, ast.Assign) and len(n.targets) == 1 and isinstance(n.targets[0], ast.Name):
                spec = _type_spec(n.value, None)
                if spec:
                    vars_[n.targets[0].id] = spec
            elif isinstance(n, ast.AnnAssign) and isinstance(n.target, ast.Name):
                vars_[n.target.id] = _type_spec(n.value, n.annotation)
            elif isinstance(n, ast.withitem) and isinstance(n.optional_vars, ast.Name):
                spec = _type_spec(n.context_expr, None)
                if spec:
                    vars_[n.optional_vars.id] = spec
    for text, line in _strings(body):
        sql += [{"table": t, "op": op, "line": line} for t, op in sql_tables(text)]
    return {"calls": calls, "vars": vars_, "sql": sql, "http": http, "local_defs": sorted(set(local_defs))}


def _http_request(call: ast.Call) -> dict | None:
    """`client.get("/orders/42?x=1")` -> {"verb": "GET", "path": "/orders/42"}: a test talking to an API."""
    f = call.func
    if (
        isinstance(f, ast.Attribute)
        and f.attr in HTTP_VERBS
        and call.args
        and isinstance(call.args[0], ast.Constant)
        and isinstance(call.args[0].value, str)
        and call.args[0].value.startswith("/")
    ):
        return {"verb": f.attr.upper(), "path": call.args[0].value.split("?", 1)[0], "line": call.lineno}
    return None


def _self_attr_types(fn: ast.FunctionDef | ast.AsyncFunctionDef) -> dict:
    out = {}
    for n in ast.walk(fn):
        target, value, ann = None, None, None
        if isinstance(n, ast.AnnAssign):
            target, value, ann = n.target, n.value, n.annotation
        elif isinstance(n, ast.Assign) and len(n.targets) == 1:
            target, value = n.targets[0], n.value
        if (
            isinstance(target, ast.Attribute)
            and isinstance(target.value, ast.Name)
            and target.value.id == "self"
        ):
            spec = _type_spec(value, ann)
            if spec and (target.attr not in out or "ann" in spec):  # an annotation beats an assignment
                out[target.attr] = spec
    return out


def _result_spec(fn: ast.FunctionDef | ast.AsyncFunctionDef, vars_: dict) -> dict | None:
    """Type spec of the first value returned or yielded: used when there is no return annotation,
    e.g. pytest fixtures (`eng = Engine(); yield eng`)."""
    for n in ast.walk(fn):
        value = n.value if isinstance(n, (ast.Return, ast.Yield)) else None
        if isinstance(value, ast.Call):
            ch = chain_of(value.func)
            if ch:
                return {"call": ch}
        if isinstance(value, ast.Name) and value.id in vars_:
            return vars_[value.id]
    return None


def _route(dec: ast.AST, fn_name: str) -> dict | None:
    if (
        isinstance(dec, ast.Call)
        and isinstance(dec.func, ast.Attribute)
        and dec.func.attr in HTTP_VERBS
        and isinstance(dec.func.value, ast.Name)
        and dec.args
        and isinstance(dec.args[0], ast.Constant)
        and isinstance(dec.args[0].value, str)
    ):
        return {
            "verb": dec.func.attr.upper(),
            "path": dec.args[0].value,
            "function": fn_name,
            "receiver": dec.func.value.id,
            "line": dec.lineno,
        }
    return None


def _function(fn: ast.FunctionDef | ast.AsyncFunctionDef, cls: str | None) -> dict:
    args = fn.args
    params = []
    for a in args.posonlyargs + args.args + args.kwonlyargs:
        params.append({"name": a.arg, "ann": ast.unparse(a.annotation) if a.annotation else None})
    facts = _body_facts(_without_docstring(fn.body))
    for p in params:  # annotated parameters are typed variables too
        if p["ann"] and p["name"] not in facts["vars"]:
            facts["vars"][p["name"]] = {"ann": p["ann"]}
    return {
        "result_spec": _result_spec(fn, facts["vars"]),
        "qualname": f"{cls}.{fn.name}" if cls else fn.name,
        "name": fn.name,
        "cls": cls,
        "line": fn.lineno,
        "end_line": fn.end_lineno,
        "params": params,
        "returns": ast.unparse(fn.returns) if fn.returns else None,
        "is_async": isinstance(fn, ast.AsyncFunctionDef),
        "decorators": [ast.unparse(d) for d in fn.decorator_list],
        "doc": _doc(fn),
        **facts,
    }


def _imports(tree: ast.Module, module: str, is_package: bool) -> list[dict]:
    out = []
    package = module if is_package else module.rpartition(".")[0]
    for n in ast.walk(tree):  # includes function-local imports (treated as module-wide: an approximation)
        if isinstance(n, ast.Import):
            for a in n.names:
                if a.asname:
                    out.append({"alias": a.asname, "target": a.name, "line": n.lineno})
                else:  # `import a.b` binds `a`
                    top = a.name.split(".")[0]
                    out.append({"alias": top, "target": top, "line": n.lineno})
                    if "." in a.name:  # keep the full name for import edges
                        out.append({"alias": None, "target": a.name, "line": n.lineno})
        elif isinstance(n, ast.ImportFrom):
            if n.level:
                base_parts = package.split(".") if package else []
                base_parts = base_parts[: len(base_parts) - (n.level - 1)] if n.level > 1 else base_parts
                base = ".".join(base_parts + ([n.module] if n.module else []))
            else:
                base = n.module or ""
            for a in n.names:
                if a.name == "*":
                    continue
                out.append(
                    {
                        "alias": a.asname or a.name,
                        "target": f"{base}.{a.name}" if base else a.name,
                        "line": n.lineno,
                    }
                )
    return out


# ---------------------------------------------------------------- entry point


def extract(path: str, source: str) -> dict:
    module = module_name(path)
    is_package = path.endswith("__init__.py")
    facts: dict = {
        "path": path,
        "module": module,
        "is_package": is_package,
        "is_test": is_test_path(path),
        "loc": source.count("\n") + (0 if source.endswith("\n") or not source else 1),
        "error": None,
        "imports": [],
        "classes": [],
        "functions": [],
        "module_vars": {},
        "routes": [],
    }
    try:
        tree = ast.parse(source, filename=path)
    except SyntaxError as exc:
        facts["error"] = f"SyntaxError: {exc.msg} (line {exc.lineno})"
        return facts

    facts["imports"] = _imports(tree, module, is_package)
    top_level: list[ast.stmt] = []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            facts["functions"].append(_function(node, None))
            facts["routes"] += [r for d in node.decorator_list if (r := _route(d, node.name))]
        elif isinstance(node, ast.ClassDef):
            attr_types: dict = {}
            for item in node.body:
                if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    facts["functions"].append(_function(item, node.name))
                    for k, v in _self_attr_types(item).items():
                        if k not in attr_types or "ann" in v:
                            attr_types[k] = v
                elif isinstance(item, ast.AnnAssign) and isinstance(item.target, ast.Name):
                    attr_types[item.target.id] = {"ann": ast.unparse(item.annotation)}
            facts["classes"].append(
                {
                    "name": node.name,
                    "line": node.lineno,
                    "end_line": node.end_lineno,
                    "bases": [ast.unparse(b) for b in node.bases],
                    "decorators": [ast.unparse(d) for d in node.decorator_list],
                    "doc": _doc(node),
                    "attr_types": attr_types,
                }
            )
        elif not isinstance(node, (ast.Import, ast.ImportFrom)):
            top_level.append(node)

    script = _body_facts(_without_docstring(top_level))
    facts["module_vars"] = script["vars"]
    if script["calls"] or script["sql"] or script["http"]:
        lines = [s.lineno for s in top_level]
        ends = [s.end_lineno or s.lineno for s in top_level]
        facts["functions"].append(
            {
                "result_spec": None,
                "qualname": SCRIPT,
                "name": SCRIPT,
                "cls": None,
                "line": min(lines),
                "end_line": max(ends),
                "params": [],
                "returns": None,
                "is_async": False,
                "decorators": [],
                "doc": None,
                **script,
            }
        )
    return facts

"""Pass 2: link per-file facts into one world: nodes + edges (ADR-0002).

No parsing happens here, only lookups in memory, so it is fast even when every file came from
the cache. Resolution is deliberately conservative: a call is linked only when the target can be
derived from definitions, imports, `self`, or simple type information. Everything else is
*counted* (external / builtin / unresolved), never guessed.
"""

from __future__ import annotations

import ast
import builtins
import re
from collections import Counter
from dataclasses import dataclass, field

from .extract import SCRIPT

PROVEN, INFERRED, PATTERN = "proven", "inferred", "pattern"
_RANK = {PROVEN: 0, INFERRED: 1, PATTERN: 2}
_BUILTINS = set(dir(builtins))
_MAX_DEPTH = 12
# method names of builtin containers: an unresolved `x.get()` is far more likely dict.get than a project
# function that happens to be called `get`, so such names are not counted as possible missed links
_CONTAINER_METHODS = (
    set(dir(dict)) | set(dir(list)) | set(dir(str)) | set(dir(set)) | set(dir(tuple)) | set(dir(bytes))
)
_TYPING_NOISE = {"None", "Optional", "Union", "typing.Optional", "typing.Union"}

Thing = tuple[str, str]  # (kind, qualified name): kind in module | class | function | instance


def _weaker(a: str, b: str) -> str:
    return a if _RANK[a] >= _RANK[b] else b


def group_of(path: str) -> str:
    """Top-level grouping shown as a district on the map."""
    parts = path.split("/")
    if parts[0] == "src":
        return parts[1] if len(parts) > 2 else "src"
    return parts[0] if len(parts) > 1 else "(root)"


@dataclass
class Ctx:
    """Where a name is being resolved."""

    module: str
    vars: dict = field(default_factory=dict)  # local name -> type spec
    cls: str | None = None  # qualified name of the enclosing class, for `self`
    params: frozenset = frozenset()  # unannotated parameters: they shadow globals; may be pytest fixtures
    path: str | None = None  # file path, to find conftest.py fixtures
    locals: frozenset = frozenset()  # functions/classes defined inside this function


# A resolution result is one of:
#   (thing, certainty)  a project module / class / function / instance-of-a-project-class
#   EXTERNAL | BUILTIN  a library or builtin object (counted, not drawn)
#   None                unknown (counted as unresolved)
EXTERNAL, BUILTIN, LOCAL = "external", "builtin", "local"  # LOCAL: a function defined inside the caller


class Resolver:
    def __init__(self, files: list[dict]):
        self.files = files
        self.mods = {f["module"]: f for f in files}
        self.alias = {}  # import name without a leading "src." (src-layout projects) -> real module
        for m in self.mods:
            if m.startswith("src.") and m[4:] not in self.mods:
                self.alias.setdefault(m[4:], m)
        self.defs: dict[str, dict[str, Thing]] = {}
        self.classes: dict[str, tuple[str, dict]] = {}
        self.funcs: dict[str, tuple[str, dict]] = {}
        self.imports: dict[str, dict[str, str]] = {}
        self.fixtures: dict[str, list[tuple[str, dict]]] = {}  # fixture name -> [(module, function facts)]
        self.path_of = {f["module"]: f["path"] for f in files}
        for f in files:
            m, d = f["module"], {}
            for c in f["classes"]:
                q = f"{m}.{c['name']}"
                d[c["name"]] = ("class", q)
                self.classes[q] = (m, c)
            for fn in f["functions"]:
                q = f"{m}.{fn['qualname']}"
                self.funcs[q] = (m, fn)
                if fn["cls"] is None and fn["name"] != SCRIPT:
                    d[fn["name"]] = ("function", q)
                    if any("fixture" in dec for dec in fn["decorators"]):
                        self.fixtures.setdefault(fn["name"], []).append((m, fn))
            self.defs[m] = d
            self.imports[m] = {i["alias"]: i["target"] for i in f["imports"] if i["alias"]}
        self._mro_cache: dict[str, list[str]] = {}

    # ------------------------------------------------------------ helpers

    def canonical(self, module: str) -> str | None:
        if module in self.mods:
            return module
        return self.alias.get(module)

    def _instance(self, t):
        """type_of() result -> resolution result."""
        if t in (EXTERNAL, BUILTIN):
            return t
        return (("instance", t), INFERRED) if t else None

    # ------------------------------------------------------------ lookups

    def resolve_dotted(self, dotted: str, depth: int = 0):
        """'pkg.mod.Class.method' -> result, following re-exports."""
        if depth > _MAX_DEPTH:
            return None
        parts = dotted.split(".")
        for i in range(len(parts), 0, -1):
            mod = self.canonical(".".join(parts[:i]))
            if mod is None:
                continue
            thing, cert = ("module", mod), PROVEN
            for attr in parts[i:]:
                r = self.member(thing, attr, depth + 1)
                if not isinstance(r, tuple):
                    return r
                thing, c = r
                cert = _weaker(cert, c)
            return thing, cert
        return None

    def member(self, thing: Thing, attr: str, depth: int):
        if depth > _MAX_DEPTH:
            return None
        kind, q = thing
        if kind == "module":
            sub = self.canonical(f"{q}.{attr}")
            if sub:
                return ("module", sub), PROVEN
            if attr in self.defs.get(q, {}):
                return self.defs[q][attr], PROVEN
            if attr in self.imports.get(q, {}):  # re-export, e.g. a package __init__
                return self.resolve_dotted(self.imports[q][attr], depth + 1) or EXTERNAL
            spec = self.mods[q]["module_vars"].get(attr)
            return self._instance(self.type_of(spec, Ctx(q), depth + 1)) if spec else None
        if kind in ("class", "instance"):
            for c in self.mro(q):
                if f"{c}.{attr}" in self.funcs:
                    return ("function", f"{c}.{attr}"), PROVEN
            for c in self.mro(q):
                cmod, cfacts = self.classes[c]
                spec = cfacts["attr_types"].get(attr)
                if spec:
                    return self._instance(self.type_of(spec, Ctx(cmod, cls=c), depth + 1))
        return None

    def mro(self, cls: str) -> list[str]:
        """The class and its project-defined base classes, breadth first."""
        if cls in self._mro_cache:
            return self._mro_cache[cls]
        out, queue = [], [cls]
        while queue:
            c = queue.pop(0)
            if c in out or c not in self.classes:
                continue
            out.append(c)
            cmod, cfacts = self.classes[c]
            for base in cfacts["bases"]:
                r = self.lookup_expr(base, Ctx(cmod))
                if isinstance(r, tuple) and r[0][0] == "class":
                    queue.append(r[0][1])
        self._mro_cache[cls] = out
        return out

    def fixture_type(self, name: str, ctx: Ctx, depth: int):
        """Type of a pytest fixture parameter: same module first, then the nearest conftest.py."""
        cands = self.fixtures.get(name, [])
        chosen = next(((m, fn) for m, fn in cands if m == ctx.module), None)
        if chosen is None and ctx.path:
            dirs = ctx.path.split("/")[:-1]
            for i in range(len(dirs), -1, -1):
                conftest = "/".join(dirs[:i] + ["conftest.py"])
                chosen = next(((m, fn) for m, fn in cands if self.path_of.get(m) == conftest), None)
                if chosen:
                    break
        if chosen is None:
            return None
        fmod, fn = chosen
        fctx = Ctx(fmod, fn["vars"], path=self.path_of.get(fmod))
        if fn["returns"]:
            t = self.type_of({"ann": fn["returns"]}, fctx, depth + 1)
            if t and t not in (EXTERNAL, BUILTIN):
                return t
        return self.type_of(fn["result_spec"], fctx, depth + 1) if fn["result_spec"] else None

    def scope(self, name: str, ctx: Ctx, depth: int):
        """Resolve the first token of a chain, following Python's lookup order."""
        if name == "self" and ctx.cls:
            return ("instance", ctx.cls), PROVEN
        if name in ctx.locals:
            return LOCAL
        if name in ctx.vars:
            return self._instance(self.type_of(ctx.vars[name], ctx, depth + 1))
        if name in ctx.params:  # parameters shadow globals; unannotated ones are known only as fixtures
            return self._instance(self.fixture_type(name, ctx, depth + 1))
        mod = ctx.module
        if name in self.defs.get(mod, {}):
            return self.defs[mod][name], PROVEN
        if name in self.imports.get(mod, {}):
            return self.resolve_dotted(self.imports[mod][name], depth + 1) or EXTERNAL
        spec = self.mods[mod]["module_vars"].get(name)
        if spec:
            return self._instance(self.type_of(spec, Ctx(mod, path=ctx.path), depth + 1))
        if name in _BUILTINS:
            return BUILTIN
        return None

    def lookup_expr(self, dotted: str, ctx: Ctx):
        """Resolve a written name like 'Base' or 'pkg.Base' (no calls)."""
        return self.resolve_chain(dotted.split("."), ctx, 0)

    def resolve_chain(self, chain: list[str], ctx: Ctx, depth: int):
        """A callee chain such as ['cart', 'total'] -> result."""
        if depth > _MAX_DEPTH or not chain:
            return None
        r = self.scope(chain[0], ctx, depth)
        if not isinstance(r, tuple):
            return r
        thing, cert = r
        for tok in chain[1:]:
            r = self.call_result(thing, depth + 1) if tok == "()" else self.member(thing, tok, depth + 1)
            if not isinstance(r, tuple):
                return r
            thing, c = r
            cert = _weaker(cert, c)
        return thing, cert

    def call_result(self, thing: Thing, depth: int):
        """What calling `thing` returns."""
        kind, q = thing
        if kind == "class":
            return ("instance", q), PROVEN
        if kind == "function":
            fmod, fn = self.funcs[q]
            cls = q.rpartition(".")[0] if fn["cls"] else None
            fctx = Ctx(fmod, fn["vars"], cls, path=self.path_of.get(fmod))
            if fn["returns"]:
                return self._instance(self.type_of({"ann": fn["returns"]}, fctx, depth + 1))
            if fn["result_spec"]:
                return self._instance(self.type_of(fn["result_spec"], fctx, depth + 1))
        return None

    def type_of(self, spec: dict | None, ctx: Ctx, depth: int):
        """Project class (qualified name), EXTERNAL, BUILTIN, or None."""
        if depth > _MAX_DEPTH or not spec:
            return None
        if spec.get("builtin"):
            return BUILTIN
        if "call" in spec:
            r = self.resolve_chain(spec["call"], ctx, depth + 1)
            if not isinstance(r, tuple):
                return r if r in (EXTERNAL, BUILTIN) else None
            res = self.call_result(r[0], depth + 1)
            if not isinstance(res, tuple):
                return res
            return res[0][1] if res[0][0] == "instance" else None
        classes, markers = set(), set()
        for name in _annotation_names(spec["ann"]):
            if name in _TYPING_NOISE:
                continue
            r = self.lookup_expr(name, Ctx(ctx.module, cls=ctx.cls))
            if isinstance(r, tuple) and r[0][0] == "class":
                classes.add(r[0][1])
            elif r in (EXTERNAL, BUILTIN):
                markers.add(r)
        if len(classes) == 1:
            return classes.pop()
        if not classes and markers:
            return EXTERNAL if EXTERNAL in markers else BUILTIN
        return None


def _annotation_names(ann: str) -> list[str]:
    """Dotted names inside an annotation string, e.g. 'requests.Session | None' -> ['requests.Session', 'None']."""
    try:
        tree = ast.parse(ann, mode="eval")
    except SyntaxError:
        return []
    names = []
    for n in ast.walk(tree):
        if isinstance(n, ast.Constant) and isinstance(n.value, str):  # forward reference "Foo"
            names += _annotation_names(n.value)
        elif isinstance(n, (ast.Name, ast.Attribute)):
            try:
                names.append(ast.unparse(n))
            except Exception:  # noqa: BLE001 - unparse of exotic nodes; skip them
                continue
    # an Attribute contains its own Name: keep only maximal dotted names
    return [n for n in names if not any(o != n and o.startswith(n + ".") for o in names)]


# ---------------------------------------------------------------- world assembly


def build_world(files: list[dict]) -> tuple[list[dict], list[dict], dict]:
    R = Resolver(files)
    nodes: list[dict] = []
    edges: dict[tuple[str, str, str], dict] = {}
    calls = Counter()

    def node(id_, kind, name, parent, group, file=None, line=None, end_line=None, **attrs):
        nodes.append(
            {
                "id": id_,
                "kind": kind,
                "name": name,
                "parent": parent,
                "group": group,
                "file": file,
                "line": line,
                "end_line": end_line,
                "attrs": attrs,
            }
        )

    def edge(source, target, kind, certainty, line=None):
        k = (source, target, kind)
        if k in edges:
            e = edges[k]
            e["count"] += 1
            if _RANK[certainty] < _RANK[e["certainty"]]:
                e["certainty"] = certainty
        else:
            edges[k] = {
                "source": source,
                "target": target,
                "kind": kind,
                "certainty": certainty,
                "line": line,
                "count": 1,
            }

    project_names = {fn["name"] for f in files for fn in f["functions"]}
    groups = sorted({group_of(f["path"]) for f in files})
    for g in groups:
        node(f"group:{g}", "group", g, None, g)

    file_of_module = {f["module"]: f["path"] for f in files}
    tables: dict[str, None] = {}

    for f in files:
        path, mod, g = f["path"], f["module"], group_of(f["path"])
        fid = f"file:{path}"
        node(
            fid,
            "file",
            path.rsplit("/", 1)[-1],
            f"group:{g}",
            g,
            path,
            1,
            f["loc"],
            module=mod,
            loc=f["loc"],
            is_test=f["is_test"],
            error=f["error"],
        )
        if f["error"]:
            continue

        # imports -> file edges
        for imp in f["imports"]:
            r = R.resolve_dotted(imp["target"])
            if isinstance(r, tuple):
                kind, q = r[0]
                target_mod = q if kind == "module" else _module_of(q, R)
                tpath = file_of_module.get(target_mod)
                if tpath and tpath != path:
                    edge(fid, f"file:{tpath}", "imports", PROVEN, imp["line"])

        for c in f["classes"]:
            cq = f"{mod}.{c['name']}"
            node(
                f"py:{cq}",
                "class",
                c["name"],
                fid,
                g,
                path,
                c["line"],
                c["end_line"],
                bases=c["bases"],
                decorators=c["decorators"],
                doc=c["doc"],
            )
            for base in c["bases"]:
                r = R.lookup_expr(base, Ctx(mod))
                if isinstance(r, tuple) and r[0][0] == "class":
                    edge(f"py:{cq}", f"py:{r[0][1]}", "inherits", PROVEN, c["line"])

        for fn in f["functions"]:
            fq = f"{mod}.{fn['qualname']}"
            is_script = fn["name"] == SCRIPT
            parent = f"py:{mod}.{fn['cls']}" if fn["cls"] else fid
            node(
                f"py:{fq}",
                "script" if is_script else "function",
                fn["name"],
                parent,
                g,
                path,
                fn["line"],
                fn["end_line"],
                method=fn["cls"] is not None,
                is_test=f["is_test"] and (is_script or fn["name"].startswith("test")),
                params=fn["params"],
                returns=fn["returns"],
                is_async=fn["is_async"],
                decorators=fn["decorators"],
                doc=fn["doc"],
                loc=(fn["end_line"] or fn["line"]) - fn["line"] + 1,
            )
            ctx = Ctx(
                mod,
                fn["vars"],
                f"{mod}.{fn['cls']}" if fn["cls"] else None,
                frozenset(p["name"] for p in fn["params"] if not p["ann"]),
                path,
                frozenset(fn.get("local_defs", [])),
            )
            for call in fn["calls"]:
                calls["total"] += 1
                r = R.resolve_chain(call["chain"], ctx, 0)
                if r in (EXTERNAL, BUILTIN, LOCAL):
                    calls[r] += 1
                    continue
                if r is None or r[0][0] not in ("function", "class"):
                    calls["unresolved"] += 1
                    name = next((t for t in reversed(call["chain"]) if t != "()"), "")
                    if name in project_names and name not in _CONTAINER_METHODS:
                        calls["unresolved_named"] += 1  # could be a project call we failed to link
                    continue
                (kind, q), cert = r
                calls["resolved"] += 1
                edge(
                    f"py:{fq}",
                    f"py:{q}",
                    "calls" if kind == "function" else "instantiates",
                    cert,
                    call["line"],
                )
            for s in fn["sql"]:
                tables[s["table"]] = None
                edge(f"py:{fq}", f"table:{s['table']}", s["op"], PATTERN, s["line"])

        for rt in f["routes"]:
            eid = f"endpoint:{rt['verb']} {rt['path']}"
            if not any(n["id"] == eid for n in nodes):
                node(
                    eid,
                    "endpoint",
                    f"{rt['verb']} {rt['path']}",
                    fid,
                    g,
                    path,
                    rt["line"],
                    rt["line"],
                    verb=rt["verb"],
                    route=rt["path"],
                )
            spec = f["module_vars"].get(rt["receiver"]) or {}
            origin = R.imports[mod].get((spec.get("call") or [""])[0], "")
            cert = PROVEN if origin.startswith("fastapi.") else PATTERN
            edge(eid, f"py:{mod}.{rt['function']}", "routes", cert, rt["line"])

    # HTTP requests (typically tests using a test client) -> the endpoint they hit: method + path match
    endpoints = []
    for f in files:
        for rt in f["routes"]:
            rx = "/".join(
                "[^/]+" if seg.startswith("{") and seg.endswith("}") else re.escape(seg)
                for seg in rt["path"].split("/")
            )
            endpoints.append((rt["verb"], re.compile(f"^{rx}/?$"), f"endpoint:{rt['verb']} {rt['path']}"))
    http = Counter()
    for f in files:
        for fn in f["functions"] if not f["error"] else []:
            for req in fn.get("http", []):
                http["total"] += 1
                hit = next(
                    (eid for verb, rx, eid in endpoints if verb == req["verb"] and rx.match(req["path"])),
                    None,
                )
                if hit:
                    http["matched"] += 1
                    edge(f"py:{f['module']}.{fn['qualname']}", hit, "requests", PATTERN, req["line"])

    if tables:
        node("group:(data)", "group", "(data)", None, "(data)")
        for t in sorted(tables):
            node(f"table:{t}", "table", t, "group:(data)", "(data)")

    stats = {
        "nodes": dict(Counter(n["kind"] for n in nodes)),
        "edges": dict(Counter(e["kind"] for e in edges.values())),
        "calls": {
            k: calls.get(k, 0)
            for k in ("total", "resolved", "local", "external", "builtin", "unresolved", "unresolved_named")
        },
        "http": {"total": http.get("total", 0), "matched": http.get("matched", 0)},
    }
    return nodes, list(edges.values()), stats


def _module_of(qual: str, R: Resolver) -> str | None:
    if qual in R.classes:
        return R.classes[qual][0]
    if qual in R.funcs:
        return R.funcs[qual][0]
    return None

"""Content-addressed cache of per-file analysis results (ADR-0003).

Key = sha256(analyser version, file path, file bytes). Unchanged files are never parsed twice,
across commits, branches and repositories. Lives outside analysed projects (~/.cache/projectviewer).
"""

from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path


def default_dir() -> Path:
    base = os.environ.get("XDG_CACHE_HOME") or Path.home() / ".cache"
    return Path(base) / "projectviewer"


class Cache:
    def __init__(self, directory: Path | None = None):
        self.dir = Path(directory) if directory else default_dir()

    @staticmethod
    def key(version: str, path: str, data: bytes) -> str:
        h = hashlib.sha256()
        h.update(version.encode())
        h.update(b"\0")
        h.update(path.encode())
        h.update(b"\0")
        h.update(data)
        return h.hexdigest()

    def _path(self, key: str) -> Path:
        return self.dir / key[:2] / f"{key}.json"

    def get(self, key: str) -> dict | None:
        try:
            return json.loads(self._path(key).read_bytes())
        except (FileNotFoundError, json.JSONDecodeError):
            return None  # a corrupt entry is treated as a miss and rewritten

    def put(self, key: str, value: dict) -> None:
        p = self._path(key)
        p.parent.mkdir(parents=True, exist_ok=True)
        tmp = p.with_suffix(f".{os.getpid()}.tmp")
        tmp.write_text(json.dumps(value, separators=(",", ":")), encoding="utf-8")
        os.replace(tmp, p)  # atomic: readers never see a half-written file

"""What changed, where, why, and what it affects.

A change set compares two worlds: a commit with its parent, or the live working copy with HEAD.
- changed:    nodes whose lines changed ("modified"), that did not exist before ("new"), or that only
              contain changed members ("contains")
- removed:    nodes that no longer exist
- upstream:   who depends on the change (callers, endpoints, tests): {node: steps away}
- downstream: what the change reaches (callees, tables): {node: steps away}
- notes:      the author's explanation per symbol, from the commit message's "Changes:" section
              (`- path::Qualified.name: text` or `- path: text`). Ported and adapted from PR World
              v5's world_diff (same idea: line ranges of the diff, then impact through the graph).
"""

from __future__ import annotations

import difflib
import re
from collections import defaultdict, deque
from pathlib import Path

from projectviewer.analyzers.python.extract import module_name
from projectviewer.analyzers.python.mapper import _git, map_repo, map_revision
from projectviewer.cache import Cache

CODE_KINDS = {"function", "script", "endpoint", "class"}
FORWARD = {"calls", "instantiates", "routes", "reads", "writes", "requests"}  # what a change reaches
BACKWARD = {"calls", "instantiates", "routes", "requests"}  # who depends on a change
MAX_HOPS = 4
EMPTY_TREE = "4b825dc642cb6eb9a060e54bf8d69288fbee4904"  # git's id for "no files": parent of a first commit

_NOTE = re.compile(r"^\s*[-*]\s+([^\s:]+?)(?:::([\w.<>]+))?:\s*(.*)$")
_REFS = re.compile(r"\b(?:refs|closes|fixes|resolves)\s+#(\d+)", re.I)


# ---------------------------------------------------------------- notes and refs from commit messages


def parse_notes(message: str) -> list[dict]:
    """The bullet lists under every line `Changes:` (each until a blank line or a non-bullet,
    non-indented line). Several sections occur when commits are squashed into one."""
    notes: list[dict] = []
    inside = False
    for line in message.splitlines():
        if line.strip().lower() == "changes:":
            inside = True
            continue
        if not inside:
            continue
        if not line.strip():
            inside = False
            continue
        m = _NOTE.match(line)
        if m:
            notes.append({"path": m.group(1), "symbol": m.group(2), "text": m.group(3).strip()})
        elif line.startswith((" ", "\t")) and notes:
            notes[-1]["text"] = f"{notes[-1]['text']} {line.strip()}"
        else:
            inside = False
    return notes


def parse_refs(message: str) -> list[int]:
    return sorted({int(n) for n in _REFS.findall(message)})


def note_target(note: dict) -> str:
    """Node id a note talks about: a symbol (py:module.Qual.name) or a whole file."""
    if note["symbol"]:
        return f"py:{module_name(note['path'])}.{note['symbol']}"
    return f"file:{note['path']}"


# ---------------------------------------------------------------- diff of two worlds


def changed_lines(diff_text: str) -> dict[str, list[tuple[int, int]]]:
    """`git diff -U0` -> {file: [(first, last)]} on the new side. Pure deletions mark the line where
    they happened."""
    ranges: dict[str, list[tuple[int, int]]] = defaultdict(list)
    cur = None
    for line in diff_text.splitlines():
        if line.startswith("+++ "):
            cur = None if line.endswith("/dev/null") else line[6:] if line.startswith("+++ b/") else line[4:]
        elif line.startswith("@@") and cur:
            m = re.match(r"@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@", line)
            if m:
                start, count = int(m.group(1)), int(m.group(2) or 1)
                ranges[cur].append((start, start + max(count, 1) - 1))
    return dict(ranges)


def renames(root: Path, *revs: str) -> dict[str, str]:
    """{new path: old path} for files git sees as moved (rename detection, -M)."""
    out = _git(root, "diff", "-M", "--name-status", "-z", *revs, "--", "*.py") or ""
    parts = out.split("\0")
    moved, i = {}, 0
    while i < len(parts) - 1:
        status = parts[i]
        if status.startswith("R"):
            moved[parts[i + 2]] = parts[i + 1]
            i += 3
        elif status:
            i += 2
        else:
            i += 1
    return moved


def _old_id(nid: str, node: dict, moved: dict[str, str]) -> str | None:
    """The id the same thing had before its file was moved (ids are derived from paths)."""
    old_path = moved.get(node.get("file") or "")
    if not old_path:
        return None
    if nid.startswith("file:"):
        return f"file:{old_path}"
    new_mod, old_mod = module_name(node["file"]), module_name(old_path)
    if nid.startswith(f"py:{new_mod}."):
        return f"py:{old_mod}.{nid[len(new_mod) + 4 :]}"
    return None


def diff_worlds(
    before: dict, after: dict, diff_text: str, max_hops: int = MAX_HOPS, moved_files: dict | None = None
) -> dict:
    bn = {n["id"]: n for n in before.get("nodes", [])}
    an = {n["id"]: n for n in after.get("nodes", [])}
    moved_files = moved_files or {}
    moved: dict[str, str] = {}
    ranges = changed_lines(diff_text)
    kids: dict[str, list[str]] = defaultdict(list)
    for n in an.values():
        if n["parent"]:
            kids[n["parent"]].append(n["id"])

    changed: dict[str, str] = {}
    for nid, n in an.items():
        if n["kind"] == "group":
            continue
        if nid not in bn:
            old = _old_id(nid, n, moved_files)
            if old and old in bn:
                moved[nid] = old  # same code, new place: not new, not removed
            else:
                changed[nid] = "new"
                continue
        f, a, b = n.get("file"), n.get("line") or 0, n.get("end_line") or n.get("line") or 0
        touched = f in ranges and (
            n["kind"] == "file"
            or (n["kind"] in CODE_KINDS and any(a <= hi and lo <= b for lo, hi in ranges[f]))
        )
        if touched:
            changed[nid] = "modified"
        elif nid in moved:
            changed[nid] = "moved"
    # a container counts as changed by its members when they explain the change
    for nid, how in list(changed.items()):
        if (
            how == "modified"
            and an[nid]["kind"] in ("class", "file")
            and any(changed.get(k) in ("new", "modified", "contains") for k in kids[nid])
        ):
            changed[nid] = "contains"
    moved_from = set(moved.values())
    removed = sorted(
        nid for nid, n in bn.items() if nid not in an and n["kind"] != "group" and nid not in moved_from
    )

    fwd: dict[str, list[str]] = defaultdict(list)
    rev: dict[str, list[str]] = defaultdict(list)
    for e in after.get("edges", []):
        if e["kind"] in FORWARD:
            fwd[e["source"]].append(e["target"])
        if e["kind"] in BACKWARD:
            rev[e["target"]].append(e["source"])
    seeds = [
        nid for nid, how in changed.items() if how in ("new", "modified") and an[nid]["kind"] in CODE_KINDS
    ]

    def reach(graph):
        hop = {s: 0 for s in seeds}
        q = deque(seeds)
        while q:
            cur = q.popleft()
            if hop[cur] >= max_hops:
                continue
            for nxt in graph.get(cur, []):
                if nxt not in hop:
                    hop[nxt] = hop[cur] + 1
                    q.append(nxt)
        return {k: v for k, v in hop.items() if v > 0 and k not in changed}

    return {
        "changed": changed,
        "moved": moved,
        "removed": removed,
        "upstream": reach(rev),
        "downstream": reach(fwd),
        "files": sorted(set(ranges) | set(moved_files)),
    }


# ---------------------------------------------------------------- change sets for refs


MOVE_SIMILARITY = 0.6  # like git's default rename threshold (50%), a little stricter


def _untracked(root: Path) -> list[str]:
    out = _git(root, "ls-files", "--others", "--exclude-standard", "-z", "--", "*.py") or ""
    return [p for p in out.split("\0") if p]


def _blob(root: Path, rev: str, path: str) -> str:
    return _git(root, "show", f"{rev}:{path}") or ""


def _unified(old: str, new: str, old_path: str, new_path: str, context: int = 0) -> str:
    lines = difflib.unified_diff(
        old.splitlines(), new.splitlines(), f"a/{old_path}", f"b/{new_path}", n=context, lineterm=""
    )
    return "\n".join(lines) + "\n"


def plain_moves(root: Path, base: str, untracked: list[str]) -> dict[str, str]:
    """{new path: old path} for files moved WITHOUT git (plain `mv`, an editor rename): a tracked file
    that disappeared and an untracked file with similar content. git cannot see these yet."""
    deleted = [p for p in (_git(root, "ls-files", "--deleted", "-z", "--", "*.py") or "").split("\0") if p]
    if not deleted or not untracked:
        return {}
    olds = {d: _blob(root, base, d).splitlines() for d in deleted}
    pairs = []
    for u in untracked:
        new = (root / u).read_text(errors="replace").splitlines()
        for d, old in olds.items():
            ratio = 1.0 if old == new else difflib.SequenceMatcher(None, old, new).ratio()
            if ratio >= MOVE_SIMILARITY:
                pairs.append((ratio, u, d))
    moved, used = {}, set()
    for _, u, d in sorted(pairs, reverse=True):  # best matches first, each file used once
        if u not in moved and d not in used:
            moved[u] = d
            used.add(d)
    return moved


def working_moves(root: Path, base: str) -> dict[str, str]:
    """All moves in the working copy: git-tracked (`git mv`, staged) and plain ones."""
    return {**renames(root, base), **plain_moves(root, base, _untracked(root))}


def _message(root: Path, sha: str) -> str:
    return _git(root, "log", "-1", "--format=%B", sha) or ""


def change_set(root: Path, ref: str, cache: Cache | None = None, after: dict | None = None) -> dict:
    """ref = "working" (uncommitted changes vs HEAD, including untracked files) or a commit."""
    root = Path(root).resolve()
    if ref == "working":
        head = _git(root, "rev-parse", "--verify", "-q", "HEAD")
        base = head.strip() if head else None
        before = map_revision(root, base, cache) if base else {"nodes": [], "edges": []}
        after = after or map_repo(root, cache)
        diff = _git(root, "diff", "-U0", "-M", base or EMPTY_TREE, "--", "*.py") or ""
        moves = working_moves(root, base) if base else {}
        for path in _untracked(root):
            text = (root / path).read_text(errors="replace")
            if path in moves:  # moved without git: only the real edits count as changed lines
                diff += "\n" + _unified(_blob(root, base, moves[path]), text, moves[path], path)
            else:  # a new file: every line is new
                diff += f"\n+++ b/{path}\n@@ -0,0 +1,{max(1, text.count(chr(10)))} @@\n"
        cs = diff_worlds(before, after, diff, moved_files=moves)
        cs.update(ref="working", sha=None, subject="Uncommitted changes", message="", refs=[], notes=[])
        return cs

    sha = (_git(root, "rev-parse", "--verify", f"{ref}^{{commit}}") or "").strip()
    if not sha:
        raise ValueError(f"unknown revision: {ref}")
    parent = (_git(root, "rev-parse", "--verify", "-q", f"{sha}^") or "").strip()
    before = map_revision(root, parent, cache) if parent else {"nodes": [], "edges": []}
    after = map_revision(root, sha, cache)
    diff = _git(root, "diff", "-U0", "-M", parent or EMPTY_TREE, sha, "--", "*.py") or ""
    cs = diff_worlds(before, after, diff, moved_files=renames(root, parent, sha) if parent else {})
    message = _message(root, sha)
    ids = {n["id"] for n in after["nodes"]}
    notes = []
    for note in parse_notes(message):
        target = note_target(note)
        notes.append({**note, "node": target if target in ids else None})
    cs.update(
        ref=ref,
        sha=sha,
        subject=message.splitlines()[0] if message else "",
        message=message,
        refs=parse_refs(message),
        notes=notes,
    )
    return cs


def commit_list(root: Path, limit: int = 40) -> list[dict]:
    """Recent commits, newest first, with how many change notes and issue references each has."""
    sep, end = "\x1f", "\x1e"
    out = _git(Path(root), "log", f"-{limit}", f"--format=%H{sep}%h{sep}%an{sep}%aI{sep}%B{end}") or ""
    commits = []
    for rec in out.split(end):
        rec = rec.strip("\n")
        if not rec:
            continue
        sha, short, author, date, message = rec.split(sep, 4)
        commits.append(
            {
                "sha": sha,
                "short": short,
                "author": author,
                "date": date,
                "subject": message.splitlines()[0] if message else "",
                "notes": len(parse_notes(message)),
                "refs": parse_refs(message),
            }
        )
    return commits


def file_diff(root: Path, ref: str, path: str) -> str:
    """Unified diff of one file for a change set (the "how"). For a moved file it compares with the
    old path, so it shows only the real edits, not the whole file as new."""
    root = Path(root).resolve()
    if ref == "working":
        head = (_git(root, "rev-parse", "--verify", "-q", "HEAD") or "").strip()
        moves = working_moves(root, head) if head else {}
        tracked = _git(root, "ls-files", "--error-unmatch", "--", path) is not None
        if path in moves and not tracked:  # plain `mv`: git has no rename to show, so diff ourselves
            return _unified(
                _blob(root, head, moves[path]),
                (root / path).read_text(errors="replace"),
                moves[path],
                path,
                3,
            )
        if not tracked:  # a new untracked file: all of it is added
            text = (root / path).read_text(errors="replace")
            return "".join(f"+{line}\n" for line in text.splitlines())
        paths = [moves[path], path] if path in moves else [path]
        return _git(root, "diff", "-M", head or EMPTY_TREE, "--", *paths) or ""
    parent = (_git(root, "rev-parse", "--verify", "-q", f"{ref}^") or "").strip()
    moves = renames(root, parent, ref) if parent else {}
    paths = [moves[path], path] if path in moves else [path]
    return _git(root, "diff", "-M", parent or EMPTY_TREE, ref, "--", *paths) or ""

"""Subscribed projects: a small JSON list in ~/.config/projectviewer/projects.json (local only)."""

from __future__ import annotations

import json
import os
import re
from pathlib import Path


def config_file() -> Path:
    base = os.environ.get("XDG_CONFIG_HOME") or Path.home() / ".config"
    return Path(base) / "projectviewer" / "projects.json"


def slug(name: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-") or "project"


def load() -> list[dict]:
    try:
        data = json.loads(config_file().read_text())
    except (FileNotFoundError, json.JSONDecodeError):
        return []
    return [p for p in data.get("projects", []) if Path(p["path"]).is_dir()]


def _save(projects: list[dict]) -> None:
    f = config_file()
    f.parent.mkdir(parents=True, exist_ok=True)
    tmp = f.with_suffix(".tmp")
    tmp.write_text(json.dumps({"projects": projects}, indent=2))
    tmp.replace(f)


def unique_id(path: Path, taken: set[str]) -> str:
    base = slug(path.name)
    pid, n = base, 2
    while pid in taken:
        pid, n = f"{base}-{n}", n + 1
    return pid


def add(path: Path) -> dict:
    path = Path(path).resolve()
    projects = load()
    for p in projects:
        if p["path"] == str(path):
            return p
    entry = {"id": unique_id(path, {p["id"] for p in projects}), "path": str(path)}
    _save([*projects, entry])
    return entry


def remove(id_or_path: str) -> bool:
    projects = load()
    target = str(Path(id_or_path).resolve()) if os.sep in id_or_path else None
    keep = [p for p in projects if p["id"] != id_or_path and p["path"] != target]
    if len(keep) == len(projects):
        return False
    _save(keep)
    return True

"""Local viewer server for one or more projects, live.

- GET /api/projects                         -> [{id, name, path, version, last_change}]   (activity)
- GET /api/p/<id>/version                   -> {"version": v}  fingerprint of the Python files (paths, mtimes, sizes)
- GET /api/p/<id>/world                     -> the world (gzip if accepted; ETag = version, 304 when unchanged)
- GET /api/p/<id>/source?file=<path>        -> {"file", "lines"}  only files the analyser itself found
- GET /api/p/<id>/commits                   -> recent commits (subject, notes count, issue refs)
- GET /api/p/<id>/changes?ref=working|<sha> -> changed / affected / notes (see changes.py)
- GET /api/p/<id>/diff?ref=…&file=<path>    -> {"diff"} unified diff of one file in that change set
- GET /api/p/<id>/events?since=<ms>         -> recent AI activity (from the Claude Code hook)
- POST /api/events                          <- `projectviewer hook` (needs header X-ProjectViewer: 1)
- everything else                           -> the built viewer (viewer/dist), single-page-app fallback

Binds to 127.0.0.1 only: nothing is reachable from other machines. The browser polls; the Phase 4
service will push changes instead (Server-Sent Events).
"""

from __future__ import annotations

import gzip
import hashlib
import json
import mimetypes
import re
import threading
import time
from collections import deque
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, unquote, urlparse

from projectviewer.analyzers.python import map_repo
from projectviewer.analyzers.python.mapper import _git, discover
from projectviewer.cache import Cache
from projectviewer.changes import change_set, commit_list, file_diff
from projectviewer.registry import unique_id

DEFAULT_WEB_DIR = Path(__file__).resolve().parents[2] / "viewer" / "dist"
MAX_SOURCE_BYTES = 2_000_000
MAX_EVENT_BYTES = 16_384
EVENTS_KEPT = 200
REF = re.compile(r"^(working|[0-9a-fA-F]{4,40}|HEAD(~\d{1,4})?)$")  # never pass anything else to git
NOT_BUILT = (
    "<!doctype html><meta charset=utf-8><title>projectViewer</title>"
    "<body style='font:15px system-ui;background:#0f1622;color:#e4ecf8;padding:40px'>"
    "<h2>The viewer is not built yet</h2><p>Run once:</p>"
    "<pre>cd viewer &amp;&amp; npm ci &amp;&amp; npm run build</pre>"
    "<p>The API is running: <a style='color:#85b7eb' href='/api/projects'>/api/projects</a></p>"
)


class Project:
    """One repository: its current world (rebuilt only when files change) and its change sets."""

    def __init__(self, pid: str, root: Path, cache: Cache | None):
        self.id = pid
        self.root = Path(root).resolve()
        self.name = self.root.name
        self.cache = cache
        self._lock = threading.Lock()
        self._version: str | None = None
        self._world: dict | None = None
        self._body = b""
        self._gz = b""
        self._files: frozenset[str] = frozenset()
        self._changes: dict[tuple[str, str], dict] = {}
        self.events: deque[dict] = deque(maxlen=EVENTS_KEPT)  # recent AI activity (memory only)
        self.last_activity = 0

    def fingerprint(self) -> tuple[str, int]:
        """(version, last change in ms): cheap, from paths + mtimes + sizes of the Python files."""
        h = hashlib.sha1()
        last = 0
        for rel in discover(self.root):
            try:
                st = (self.root / rel).stat()
            except FileNotFoundError:
                continue
            last = max(last, st.st_mtime_ns)
            h.update(f"{rel}\0{st.st_mtime_ns}\0{st.st_size}\n".encode())
        return h.hexdigest()[:16], last // 1_000_000

    def current(self) -> tuple[str, bytes, bytes]:
        """(version, json bytes, gzipped json bytes); re-maps only if the version changed."""
        with self._lock:
            v, _ = self.fingerprint()
            if v != self._version:
                world = map_repo(self.root, cache=self.cache)
                world["version"] = v
                self._world = world
                self._body = json.dumps(world, separators=(",", ":")).encode()
                self._gz = gzip.compress(self._body, compresslevel=5)
                self._files = frozenset(n["file"] for n in world["nodes"] if n["kind"] == "file")
                self._version = v
            return self._version, self._body, self._gz

    def is_project_file(self, rel: str) -> bool:
        self.current()
        return rel in self._files

    def changes(self, ref: str) -> dict:
        version, _, _ = self.current()
        if ref != "working":  # HEAD / HEAD~n move with every commit: cache by the commit they name now
            sha = (_git(self.root, "rev-parse", "--verify", "-q", f"{ref}^{{commit}}") or "").strip()
            if not sha:
                raise ValueError(f"unknown revision: {ref}")
            ref = sha
        key = (ref, version if ref == "working" else "")  # commits never change; the working copy does
        with self._lock:
            hit = self._changes.get(key)
        if hit is None:
            hit = change_set(self.root, ref, self.cache, after=self._world if ref == "working" else None)
            with self._lock:
                if len(self._changes) > 200:
                    self._changes.clear()
                self._changes[key] = hit
        return hit


def make_server(
    roots: Path | list[Path],
    port: int = 8765,
    web_dir: Path | None = None,
    cache: Cache | None = None,
    ids: list[str] | None = None,
) -> ThreadingHTTPServer:
    roots = [roots] if isinstance(roots, (str, Path)) else list(roots)
    projects: dict[str, Project] = {}
    for i, root in enumerate(roots):
        pid = ids[i] if ids else unique_id(Path(root).resolve(), set(projects))
        projects[pid] = Project(pid, root, cache)
    web = Path(web_dir or DEFAULT_WEB_DIR).resolve()

    def record_event(ev: dict) -> bool:
        """Attach an event to the project it happened in (by file, else working directory)."""
        where = ev.get("file") or ev.get("cwd") or ""
        try:
            where_path = Path(str(where)).resolve()
        except (OSError, ValueError):
            return False
        for p in projects.values():
            if where_path == p.root or where_path.is_relative_to(p.root):
                now = int(time.time() * 1000)
                clean = {
                    k: str(v)[:500] for k, v in ev.items() if k in ("event", "session", "tool", "prompt")
                }
                clean["at"] = now
                if ev.get("file"):
                    clean["file"] = where_path.relative_to(p.root).as_posix()
                p.events.append(clean)
                p.last_activity = now
                return True
        return False

    class Handler(BaseHTTPRequestHandler):
        server_version = "projectViewer"

        def log_message(self, *args):  # keep the terminal quiet
            pass

        def _send(self, status, body: bytes, ctype="application/json", headers=None):
            self.send_response(status)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            for k, v in (headers or {}).items():
                self.send_header(k, v)
            self.end_headers()
            if self.command != "HEAD":
                self.wfile.write(body)

        def _json(self, obj, status=HTTPStatus.OK):
            self._send(status, json.dumps(obj).encode())

        def do_GET(self):  # noqa: N802 - http.server naming
            url = urlparse(self.path)
            path = unquote(url.path)
            q = {k: v[0] for k, v in parse_qs(url.query).items()}
            try:
                if path == "/api/projects":
                    return self._projects()
                m = re.match(r"^/api/p/([^/]+)/(\w+)$", path)
                if m:
                    p = projects.get(m.group(1))
                    if p is None:
                        return self._json({"error": "unknown project"}, HTTPStatus.NOT_FOUND)
                    return self._project(p, m.group(2), q)
                if path.startswith("/api/"):
                    return self._json({"error": "not found"}, HTTPStatus.NOT_FOUND)
                return self._static(path)
            except BrokenPipeError:
                return None

        do_HEAD = do_GET

        def do_POST(self):  # noqa: N802 - http.server naming
            if urlparse(self.path).path != "/api/events":
                return self._json({"error": "not found"}, HTTPStatus.NOT_FOUND)
            # A custom header cannot be sent by a plain cross-site form: web pages can't inject events.
            if self.headers.get("X-ProjectViewer") != "1":
                return self._json({"error": "missing X-ProjectViewer header"}, HTTPStatus.FORBIDDEN)
            size = int(self.headers.get("Content-Length") or 0)
            if size > MAX_EVENT_BYTES:
                return self._json({"error": "event too large"}, HTTPStatus.REQUEST_ENTITY_TOO_LARGE)
            try:
                ev = json.loads(self.rfile.read(size) or b"{}")
            except json.JSONDecodeError:
                return self._json({"error": "bad json"}, HTTPStatus.BAD_REQUEST)
            if not isinstance(ev, dict):
                return self._json({"error": "bad event"}, HTTPStatus.BAD_REQUEST)
            accepted = record_event(ev)
            return self._json({"accepted": accepted}, HTTPStatus.ACCEPTED)

        def _projects(self):
            out = []
            for p in projects.values():
                version, last = p.fingerprint()
                out.append(
                    {
                        "id": p.id,
                        "name": p.name,
                        "path": str(p.root),
                        "version": version,
                        "last_change": last,
                        "last_activity": p.last_activity,
                    }
                )
            self._json(out)

        def _project(self, p: Project, what: str, q: dict):
            if what == "version":
                return self._json({"version": p.fingerprint()[0]})
            if what == "world":
                return self._world(p)
            if what == "source":
                return self._source(p, q.get("file", ""))
            if what == "events":
                since = int(q.get("since", "0") or 0) if q.get("since", "0").isdigit() else 0
                return self._json([e for e in list(p.events) if e["at"] > since])
            if what == "commits":
                return self._json(commit_list(p.root))
            if what in ("changes", "diff"):
                ref = q.get("ref", "")
                if not REF.match(ref):
                    return self._json({"error": "bad ref"}, HTTPStatus.BAD_REQUEST)
                try:
                    cs = p.changes(ref)
                except ValueError as exc:
                    return self._json({"error": str(exc)}, HTTPStatus.NOT_FOUND)
                if what == "changes":
                    return self._json(cs)
                rel = q.get("file", "")
                if rel not in cs["files"] and not p.is_project_file(rel):
                    return self._json({"error": "not a file of this change"}, HTTPStatus.NOT_FOUND)
                return self._json({"file": rel, "diff": file_diff(p.root, ref, rel)})
            return self._json({"error": "not found"}, HTTPStatus.NOT_FOUND)

        def _world(self, p: Project):
            version, body, gz = p.current()
            etag = f'"{version}"'
            if self.headers.get("If-None-Match") == etag:
                self.send_response(HTTPStatus.NOT_MODIFIED)
                self.send_header("ETag", etag)
                self.end_headers()
                return
            headers = {"ETag": etag}
            if "gzip" in (self.headers.get("Accept-Encoding") or ""):
                headers["Content-Encoding"] = "gzip"
                body = gz
            self._send(HTTPStatus.OK, body, headers=headers)

        def _source(self, p: Project, rel: str):
            # Only files the analyser found in this repo: no paths outside it, no other file types.
            if not rel or not p.is_project_file(rel):
                return self._json({"error": "not a project file"}, HTTPStatus.NOT_FOUND)
            f = p.root / rel
            if f.stat().st_size > MAX_SOURCE_BYTES:
                return self._json({"error": "file too large"}, HTTPStatus.REQUEST_ENTITY_TOO_LARGE)
            self._json({"file": rel, "lines": f.read_text(encoding="utf-8", errors="replace").splitlines()})

        def _static(self, path: str):
            if not (web / "index.html").is_file():
                return self._send(HTTPStatus.OK, NOT_BUILT.encode(), "text/html; charset=utf-8")
            target = (web / path.lstrip("/")).resolve()
            if not target.is_relative_to(web):
                return self._json({"error": "bad path"}, HTTPStatus.BAD_REQUEST)
            if not target.is_file():
                target = web / "index.html"  # single-page app: client-side routes
            ctype = mimetypes.guess_type(target.name)[0] or "application/octet-stream"
            if ctype.startswith("text/") or ctype in ("application/javascript", "application/json"):
                ctype += "; charset=utf-8"
            self._send(HTTPStatus.OK, target.read_bytes(), ctype)

    srv = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    srv.projects = projects
    return srv

