export const TEXT_DIM = [150, 166, 196];

export const CERTAINTY_ALPHA = { proven: 235, inferred: 165, pattern: 120 };

export const mix = (a, b, t) => [0, 1, 2].map((i) => Math.round(a[i] * (1 - t) + b[i] * t));
export const dim = (c, f = 0.5) => [c[0] * f, c[1] * f, c[2] * f];
export const css = (c) => `rgb(${c.join(",")})`;

// Layout of ONE level of the folder tree: the children of the current focus become blocks on a
// ground plane, separated by "streets". Size = number of functions inside (lines of code when every
// block on the level is a single function). Footprint grows gently with size, so small things stay
// clickable; height grows with size relative to the biggest sibling (bigger = clearly taller).
import { hierarchy, treemap, treemapSquarify } from "d3-hierarchy";

export const WIDTH = 1000;
export const HEIGHT = 640;
const STREET = 22; // gap between blocks
const MIN_H = 12;
const MAX_H = 170;

export function layoutLevel(focus) {
  const kids = focus?.children || [];
  const rects = new Map();
  if (!kids.length) return { blocks: [], rects, width: WIDTH, height: HEIGHT, zTop: 0 };
  const byFunctions = Math.max(...kids.map((k) => k.stats.fn)) > 1;
  const size = (t) => Math.max(byFunctions ? 0.5 : 1, byFunctions ? t.stats.fn : t.stats.loc);
  const maxSize = Math.max(1, ...kids.map(size));

  const root = hierarchy({ children: kids.map((t) => ({ t })) })
    .sum((d) => (d.t ? 2 + 3 * Math.sqrt(size(d.t)) : 0))
    .sort((a, b) => b.value - a.value || (a.data.t?.id < b.data.t?.id ? -1 : 1));
  treemap().tile(treemapSquarify.ratio(1.4)).size([WIDTH, HEIGHT]).paddingInner(STREET).paddingOuter(STREET).round(false)(root);

  const blocks = root.leaves().map((d) => {
    const t = d.data.t;
    const b = { id: t.id, t, x0: d.x0, y0: d.y0, x1: d.x1, y1: d.y1, z0: 0, h: MIN_H + (MAX_H - MIN_H) * Math.sqrt(size(t) / maxSize) };
    b.zTop = b.h;
    rects.set(b.id, b);
    return b;
  });
  return { blocks, rects, width: WIDTH, height: HEIGHT, zTop: Math.max(...blocks.map((b) => b.h)), measure: byFunctions ? "functions" : "lines" };
}

// The roof of a block, divided into its children (one level deep): shows how a module is organised
// without opening it. Area follows the same size measure as the blocks. No division for 0–1 children.
export function roofTiles(block, inset = 4, gap = 2.5) {
  const kids = block.t.children;
  if (kids.length < 2) return [];
  const w = block.x1 - block.x0 - 2 * inset;
  const h = block.y1 - block.y0 - 2 * inset;
  if (w <= 4 || h <= 4) return [];
  const byFunctions = Math.max(...kids.map((k) => k.stats.fn)) > 1;
  const root = hierarchy({ children: kids.map((t) => ({ t })) })
    .sum((d) => (d.t ? Math.max(0.6, byFunctions ? d.t.stats.fn : Math.sqrt(d.t.stats.loc)) : 0))
    .sort((a, b) => b.value - a.value || (a.data.t?.id < b.data.t?.id ? -1 : 1));
  treemap().tile(treemapSquarify.ratio(1.3)).size([w, h]).paddingInner(gap).round(false)(root);
  const x = block.x0 + inset;
  const y = block.y0 + inset;
  return root.leaves().map((d) => ({ id: d.data.t.id, t: d.data.t, parent: block.id, x0: x + d.x0, y0: y + d.y0, x1: x + d.x1, y1: y + d.y1, z: block.h }));
}

export const centre = (r) => [(r.x0 + r.x1) / 2, (r.y0 + r.y1) / 2];

// Curved link between two points (quadratic Bézier), as a polyline for deck.gl's PathLayer.
export function curve(a, b, bend = 0.18, steps = 18) {
  const [x0, y0] = a;
  const [x1, y1] = b;
  const cx = (x0 + x1) / 2 - (y1 - y0) * bend;
  const cy = (y0 + y1) / 2 + (x1 - x0) * bend;
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const u = 1 - t;
    pts.push([u * u * x0 + 2 * u * t * cx + t * t * x1, u * u * y0 + 2 * u * t * cy + t * t * y1]);
  }
  return pts;
}

// Arc between two block tops, lifted in the middle in proportion to its length.
export function curve3d(a, b, lift = 0.22, steps = 20) {
  const len = Math.hypot(b[0] - a[0], b[1] - a[1]);
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    pts.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t + Math.sin(Math.PI * t) * len * lift]);
  }
  pts[steps] = [...b];
  return pts;
}

// Camera that fits a rectangle into a viewport of (width x height) pixels (flat map).
export function fit(r, width, height, margin = 1.12) {
  const w = Math.max(1, r.x1 - r.x0);
  const h = Math.max(1, r.y1 - r.y0);
  const zoom = Math.log2(Math.min(width / (w * margin), height / (h * margin)));
  return { target: [(r.x0 + r.x1) / 2, (r.y0 + r.y1) / 2, 0], zoom: Math.max(-4, Math.min(9, zoom)) };
}

// The world as an index: lookups, test reach, links for a selection, group-level overview links.
// Pure functions (no React, no DOM), unit-tested with `npm test`.

const CALLISH = new Set(["calls", "instantiates"]);

function push(map, key, value) {
  if (!map.has(key)) map.set(key, []);
  map.get(key).push(value);
}

export function indexWorld(world) {
  const byId = new Map();
  const kids = new Map();
  const out = new Map();
  const inn = new Map();
  for (const n of world.nodes) byId.set(n.id, n);
  for (const n of world.nodes) push(kids, n.parent ?? null, n);
  for (const e of world.edges) {
    push(out, e.source, e);
    push(inn, e.target, e);
  }

  // Which code do the tests reach? Direct = called by a test, or the handler of an endpoint a test
  // requests over HTTP; reach = within 4 calls of that.
  const testedDirect = new Set();
  for (const n of world.nodes) {
    if (!n.attrs?.is_test) continue;
    for (const e of out.get(n.id) || []) {
      if (CALLISH.has(e.kind)) testedDirect.add(e.target);
      if (e.kind === "requests") for (const r of out.get(e.target) || []) if (r.kind === "routes") testedDirect.add(r.target);
    }
  }
  const testedReach = new Set(testedDirect);
  let frontier = [...testedDirect];
  for (let hop = 0; hop < 4 && frontier.length; hop++) {
    const next = [];
    for (const id of frontier)
      for (const e of out.get(id) || [])
        if (CALLISH.has(e.kind) && !testedReach.has(e.target)) {
          testedReach.add(e.target);
          next.push(e.target);
        }
    frontier = next;
  }

  return { world, nodes: world.nodes, edges: world.edges, byId, kids, out, inn, testedDirect, testedReach };
}

export function children(ix, id) {
  return ix.kids.get(id) || [];
}

export function descendants(ix, id) {
  const res = [];
  const stack = [id];
  while (stack.length) {
    for (const k of children(ix, stack.pop())) {
      res.push(k.id);
      stack.push(k.id);
    }
  }
  return res;
}

export function ancestors(ix, id) {
  const res = [];
  let n = ix.byId.get(id);
  while (n && n.parent) {
    res.unshift(n.parent);
    n = ix.byId.get(n.parent);
  }
  return res;
}

// Links between the selected thing (including everything inside it) and the rest of the world.
export function linksFor(ix, selId, max = 600) {
  const inside = new Set([selId, ...descendants(ix, selId)]);
  const res = [];
  for (const id of inside) {
    for (const e of ix.out.get(id) || []) if (!inside.has(e.target)) res.push({ e, dir: "out" });
    for (const e of ix.inn.get(id) || []) if (!inside.has(e.source)) res.push({ e, dir: "in" });
    if (res.length >= max) break;
  }
  return { inside, links: res.slice(0, max) };
}

// Overview: how the top-level groups depend on each other (calls, instantiation, data access).
export function groupLinks(ix, kinds = ["calls", "instantiates", "reads", "writes"]) {
  const want = new Set(kinds);
  const pairs = new Map();
  for (const e of ix.edges) {
    if (!want.has(e.kind)) continue;
    const s = ix.byId.get(e.source);
    const t = ix.byId.get(e.target);
    if (!s || !t || s.group === t.group) continue;
    const key = `group:${s.group}\u0000group:${t.group}`;
    pairs.set(key, (pairs.get(key) || 0) + e.count);
  }
  return [...pairs.entries()].map(([k, count]) => {
    const [source, target] = k.split("\u0000");
    return { source, target, count };
  });
}

// Short human name: methods get their class, scripts their file.
export function displayName(ix, n) {
  if (!n) return "?";
  if (n.kind === "script") return `${n.file} (top level)`;
  if (n.kind === "function") {
    const p = ix.byId.get(n.parent);
    return p && p.kind === "class" ? `${p.name}.${n.name}()` : `${n.name}()`;
  }
  return n.name;
}

export function search(ix, query, limit = 12) {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const rank = { function: 0, class: 1, endpoint: 2, table: 3, file: 4, group: 5, script: 6 };
  return ix.nodes
    .filter((n) => n.name.toLowerCase().includes(q) || (n.kind === "file" && n.file.toLowerCase().includes(q)))
    .sort(
      (a, b) =>
        (a.name.toLowerCase() === q ? -1 : 0) - (b.name.toLowerCase() === q ? -1 : 0) ||
        (rank[a.kind] ?? 9) - (rank[b.kind] ?? 9) ||
        a.name.length - b.name.length,
    )
    .slice(0, limit);
}

// Unit tests for the viewer's pure logic. Run: npm test  (Node's built-in test runner)
import assert from "node:assert/strict";
import { test } from "node:test";
import { curve, curve3d, fit } from "./layout.js";
import { ancestors, descendants, groupLinks, indexWorld, linksFor, search } from "./model.js";

const node = (id, kind, name, parent, group, attrs = {}) => ({ id, kind, name, parent, group, file: "x.py", line: 1, end_line: 5, attrs });
const edge = (source, target, kind = "calls") => ({ source, target, kind, certainty: "proven", count: 1 });

const world = {
  nodes: [
    node("group:shop", "group", "shop", null, "shop"),
    node("group:tests", "group", "tests", null, "tests"),
    node("file:shop/a.py", "file", "a.py", "group:shop", "shop", { loc: 40 }),
    node("py:shop.a.Cart", "class", "Cart", "file:shop/a.py", "shop"),
    node("py:shop.a.Cart.total", "function", "total", "py:shop.a.Cart", "shop", { loc: 10 }),
    node("py:shop.a.helper", "function", "helper", "file:shop/a.py", "shop", { loc: 5 }),
    node("py:shop.a.deep", "function", "deep", "file:shop/a.py", "shop", { loc: 5 }),
    node("file:tests/t.py", "file", "t.py", "group:tests", "tests", { loc: 10 }),
    node("py:tests.t.test_total", "function", "test_total", "file:tests/t.py", "tests", { loc: 3, is_test: true }),
  ],
  edges: [
    edge("py:tests.t.test_total", "py:shop.a.Cart.total"),
    edge("py:shop.a.Cart.total", "py:shop.a.helper"),
    edge("py:shop.a.helper", "py:shop.a.deep"),
  ],
};

test("index: hierarchy and lookups", () => {
  const ix = indexWorld(world);
  assert.deepEqual(ancestors(ix, "py:shop.a.Cart.total"), ["group:shop", "file:shop/a.py", "py:shop.a.Cart"]);
  assert.ok(descendants(ix, "group:shop").includes("py:shop.a.Cart.total"));
});

test("test reach: direct vs indirect", () => {
  const ix = indexWorld(world);
  assert.ok(ix.testedDirect.has("py:shop.a.Cart.total"));
  assert.ok(!ix.testedDirect.has("py:shop.a.helper"));
  assert.ok(ix.testedReach.has("py:shop.a.deep"));
});

test("links of a container only cross its boundary", () => {
  const ix = indexWorld(world);
  const { links } = linksFor(ix, "file:shop/a.py");
  assert.deepEqual(
    links.map((l) => [l.e.source, l.dir]),
    [["py:tests.t.test_total", "in"]],
  );
});

test("group overview aggregates cross-group links", () => {
  const ix = indexWorld(world);
  assert.deepEqual(groupLinks(ix), [{ source: "group:tests", target: "group:shop", count: 1 }]);
});

test("search ranks exact names and functions first", () => {
  const ix = indexWorld(world);
  assert.equal(search(ix, "total")[0].id, "py:shop.a.Cart.total");
});

test("curve starts and ends at the endpoints; fit centres the box", () => {
  const pts = curve([0, 0], [10, 0]);
  assert.deepEqual(pts[0], [0, 0]);
  assert.deepEqual(pts.at(-1), [10, 0]);
  const v = fit({ x0: 0, y0: 0, x1: 100, y1: 50 }, 1000, 500);
  assert.deepEqual(v.target, [50, 25, 0]);
});

test("3D curve lifts in the middle and ends on the targets", () => {
  const pts = curve3d([0, 0, 10], [100, 0, 20]);
  assert.deepEqual(pts[0], [0, 0, 10]);
  assert.deepEqual(pts.at(-1), [100, 0, 20]);
  assert.ok(pts[Math.floor(pts.length / 2)][2] > 20);
});

test("tests that call an API over HTTP reach the endpoint's handler directly", () => {
  const ix = indexWorld({
    nodes: [
      { id: "py:t.test_api", kind: "function", name: "test_api", parent: null, attrs: { is_test: true } },
      { id: "endpoint:GET /x", kind: "endpoint", name: "GET /x", parent: null, attrs: {} },
      { id: "py:api.handler", kind: "function", name: "handler", parent: null, attrs: {} },
      { id: "py:core.work", kind: "function", name: "work", parent: null, attrs: {} },
    ],
    edges: [
      { source: "py:t.test_api", target: "endpoint:GET /x", kind: "requests", certainty: "pattern", count: 1 },
      { source: "endpoint:GET /x", target: "py:api.handler", kind: "routes", certainty: "proven", count: 1 },
      { source: "py:api.handler", target: "py:core.work", kind: "calls", certainty: "proven", count: 1 },
    ],
  });
  assert.ok(ix.testedDirect.has("py:api.handler"));
  assert.ok(ix.testedReach.has("py:core.work"));
});

// The project as a FOLDER tree: root › folders › files › classes › functions (+ a Database block for
// tables). The map shows one level of it at a time. Pure logic, unit-tested with `npm test`.

const CALLISH = new Set(["calls", "instantiates"]);
const DATA = new Set(["reads", "writes"]);
// Folders that only package code (src-layout) carry no meaning of their own: their contents are
// shown as top-level modules.
const TRANSPARENT_ROOTS = new Set(["src"]);
const EMPTY = () => ({ fn: 0, loc: 0, folders: 0, files: 0, testFiles: 0, classes: 0, functions: 0, tests: 0, endpoints: 0, tables: 0, tested: 0, data: 0 });

export function buildTree(ix, rootName = "project") {
  const T = new Map();
  const add = (id, kind, name, parent, n = null, path = "") => {
    const t = { id, kind, name, parent, children: [], n, path, stats: EMPTY() };
    T.set(id, t);
    if (parent) T.get(parent).children.push(t);
    return t;
  };
  const root = add("root", "root", rootName, null);

  // folders and files, from the file paths
  for (const n of ix.nodes) {
    if (n.kind !== "file") continue;
    let parent = "root";
    let acc = "";
    const dirs = n.file.split("/").slice(0, -1);
    dirs.forEach((part, i) => {
      acc = acc ? `${acc}/${part}` : part;
      if (i === 0 && TRANSPARENT_ROOTS.has(part)) return;
      const id = `dir:${acc}`;
      if (!T.has(id)) add(id, "folder", part, parent, null, acc);
      parent = id;
    });
    add(n.id, "file", n.name, parent, n, n.file);
  }
  const tables = ix.nodes.filter((n) => n.kind === "table");
  if (tables.length) {
    add("db", "database", "Database", "root");
    for (const n of tables) add(n.id, "table", n.name, "db", n);
  }
  // code inside files and classes (a parent always exists before its children are placed)
  let pending = ix.nodes.filter((n) => n.kind === "class" || n.kind === "function" || n.kind === "script" || n.kind === "endpoint");
  while (pending.length) {
    const next = [];
    for (const n of pending) {
      if (T.has(n.parent)) add(n.id, n.kind, n.kind === "script" ? "top-level code" : n.name, n.parent, n, n.file);
      else next.push(n);
    }
    if (next.length === pending.length) break; // orphans: skip rather than loop forever
    pending = next;
  }

  const touchesData = (id) => (ix.out.get(id) || []).some((e) => DATA.has(e.kind));
  const visit = (t) => {
    const s = t.stats;
    for (const c of t.children) {
      visit(c);
      for (const k of Object.keys(s)) s[k] += c.stats[k];
    }
    const n = t.n;
    if (t.kind === "folder") s.folders += 1;
    else if (t.kind === "file") {
      s.files += 1;
      if (n.attrs?.is_test) s.testFiles += 1;
      s.loc = n.attrs?.loc || s.loc; // the whole file, not only the code inside definitions
    } else if (t.kind === "class") {
      s.classes += 1;
      s.loc = Math.max(s.loc, n.end_line && n.line ? n.end_line - n.line + 1 : 1);
    } else if (t.kind === "function") {
      s.fn += 1;
      if (n.attrs?.is_test) s.tests += 1;
      else {
        s.functions += 1;
        if (ix.testedReach.has(n.id)) s.tested += 1;
      }
      if (touchesData(n.id)) s.data += 1;
      s.loc = n.attrs?.loc || 1;
    } else if (t.kind === "script") {
      if (touchesData(n.id)) s.data += 1;
      s.loc = n.attrs?.loc || 1;
    } else if (t.kind === "endpoint") {
      s.endpoints += 1;
      s.loc = 1;
    } else if (t.kind === "table") {
      s.tables += 1;
    }
    t.isTest = t.kind === "function" ? !!n.attrs?.is_test : s.files > 0 && s.testFiles === s.files;
  };
  visit(root);
  return { T, root };
}

export function treeAncestors(tree, id) {
  const res = [];
  let t = tree.T.get(id);
  while (t && t.parent) {
    res.unshift(t.parent);
    t = tree.T.get(t.parent);
  }
  return res;
}

export function subtreeIds(t, out = []) {
  out.push(t.id);
  for (const c of t.children) subtreeIds(c, out);
  return out;
}

// Map every world node inside `focus` to the child block of `focus` that contains it.
export function blockIndex(tree, focusId) {
  const blockOf = new Map();
  const focus = tree.T.get(focusId);
  for (const c of focus?.children || []) for (const id of subtreeIds(c)) blockOf.set(id, c.id);
  return blockOf;
}

// Dependencies between the blocks of one level, summed: calls, object creation, and data access.
export function levelLinks(ix, tree, focusId, kinds = ["calls", "instantiates", "reads", "writes"]) {
  const want = new Set(kinds);
  const blockOf = blockIndex(tree, focusId);
  const pairs = new Map();
  for (const e of ix.edges) {
    if (!want.has(e.kind)) continue;
    const a = blockOf.get(e.source);
    const b = blockOf.get(e.target);
    if (!a || !b || a === b) continue;
    const key = `${a}\u0000${b}`;
    pairs.set(key, (pairs.get(key) || 0) + (e.count || 1));
  }
  return [...pairs.entries()].map(([k, count]) => {
    const [source, target] = k.split("\u0000");
    return { source, target, count };
  });
}

// Links from a block to everything outside it, summed per sibling block at the current level. When the
// other end lies outside the current level, it is named by its top-level module, marked "@" (elsewhere).
export function blockDeps(ix, tree, focusId, blockId) {
  const sibling = blockIndex(tree, focusId);
  const top = focusId === "root" ? sibling : blockIndex(tree, "root");
  const blockOf = { get: (id) => sibling.get(id) || (top.get(id) ? `@${top.get(id)}` : undefined) };
  const inside = new Set(subtreeIds(tree.T.get(blockId)));
  const out = new Map();
  const inn = new Map();
  const bump = (m, k, e) => m.set(k, (m.get(k) || 0) + (e.count || 1));
  for (const id of inside) {
    for (const e of ix.out.get(id) || []) if (!inside.has(e.target) && (CALLISH.has(e.kind) || DATA.has(e.kind))) bump(out, blockOf.get(e.target) || "elsewhere", e);
    for (const e of ix.inn.get(id) || []) if (!inside.has(e.source) && (CALLISH.has(e.kind) || DATA.has(e.kind))) bump(inn, blockOf.get(e.source) || "elsewhere", e);
  }
  const sorted = (m) => [...m.entries()].sort((a, b) => b[1] - a[1]);
  return { out: sorted(out), in: sorted(inn) };
}

// Change overlay: a block is "changed" when anything inside it changed, else "affected" when anything
// inside it depends on or is reached by the change.
export function changeMarks(tree, cs) {
  const rank = { changed: 3, moved: 2, affected: 1 };
  const marks = new Map();
  const up = (id, v) => {
    for (let t = tree.T.get(id); t; t = t.parent ? tree.T.get(t.parent) : null) {
      if ((rank[marks.get(t.id)] || 0) >= rank[v]) break; // ancestors are already marked at least this strongly
      marks.set(t.id, v);
    }
  };
  for (const [id, how] of Object.entries(cs?.changed || {})) up(id, how === "moved" ? "moved" : "changed");
  for (const id of [...Object.keys(cs?.upstream || {}), ...Object.keys(cs?.downstream || {})]) up(id, "affected");
  return marks;
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { layoutLevel, roofTiles } from "./layout.js";
import { indexWorld } from "./model.js";
import { blockDeps, buildTree, changeMarks, levelLinks, treeAncestors } from "./tree.js";

const node = (id, kind, name, parent, file, attrs = {}) => ({ id, kind, name, parent, group: "g", file, line: 1, end_line: 5, attrs });
const edge = (source, target, kind = "calls") => ({ source, target, kind, certainty: "proven", count: 1 });

const world = {
  nodes: [
    node("group:src", "group", "src", null),
    node("file:src/shop/cart.py", "file", "cart.py", "group:src", "src/shop/cart.py", { loc: 120 }),
    node("py:src.shop.cart.Cart", "class", "Cart", "file:src/shop/cart.py", "src/shop/cart.py"),
    node("py:src.shop.cart.Cart.total", "function", "total", "py:src.shop.cart.Cart", "src/shop/cart.py", { loc: 30 }),
    node("file:src/shop/tax.py", "file", "tax.py", "group:src", "src/shop/tax.py", { loc: 20 }),
    node("py:src.shop.tax.rate", "function", "rate", "file:src/shop/tax.py", "src/shop/tax.py", { loc: 8 }),
    node("file:src/api.py", "file", "api.py", "group:src", "src/api.py", { loc: 40 }),
    node("py:src.api.get_total", "function", "get_total", "file:src/api.py", "src/api.py", { loc: 6 }),
    node("endpoint:GET /total", "endpoint", "GET /total", "file:src/api.py", "src/api.py"),
    node("group:tests", "group", "tests", null),
    node("file:tests/test_cart.py", "file", "test_cart.py", "group:tests", "tests/test_cart.py", { loc: 10, is_test: true }),
    node("py:tests.test_cart.test_total", "function", "test_total", "file:tests/test_cart.py", "tests/test_cart.py", { loc: 3, is_test: true }),
    node("group:(data)", "group", "(data)", null),
    node("table:orders", "table", "orders", "group:(data)"),
  ],
  edges: [
    edge("py:src.api.get_total", "py:src.shop.cart.Cart.total"),
    edge("py:src.shop.cart.Cart.total", "py:src.shop.tax.rate"),
    edge("py:tests.test_cart.test_total", "py:src.shop.cart.Cart.total"),
    edge("py:src.shop.cart.Cart.total", "table:orders", "reads"),
    edge("endpoint:GET /total", "py:src.api.get_total", "routes"),
  ],
};

const setup = () => {
  const ix = indexWorld(world);
  return { ix, tree: buildTree(ix, "shop") };
};

test("the tree follows the folder structure; src/ is transparent; tables form a Database block", () => {
  const { tree } = setup();
  const names = (id) => tree.T.get(id).children.map((c) => c.name).sort();
  assert.deepEqual(names("root"), ["Database", "api.py", "shop", "tests"]);
  assert.ok(!tree.T.has("dir:src"));
  assert.deepEqual(names("dir:src/shop"), ["cart.py", "tax.py"]);
  assert.deepEqual(names("py:src.shop.cart.Cart"), ["total"]);
  assert.deepEqual(treeAncestors(tree, "py:src.shop.cart.Cart.total"), ["root", "dir:src/shop", "file:src/shop/cart.py", "py:src.shop.cart.Cart"]);
});

test("stats roll up: lines, files, functions, tests, endpoints, tested share", () => {
  const { tree } = setup();
  const s = tree.T.get("root").stats;
  assert.equal(s.loc, 190);
  assert.equal(s.files, 4);
  assert.equal(s.functions, 3);
  assert.equal(s.fn, 4); // all functions, tests included: the size measure
  assert.equal(s.endpoints, 1);
  assert.equal(s.tested, 2); // total (direct) + rate (indirect)
  assert.equal(s.data, 1);
  assert.equal(tree.T.get("dir:tests").isTest, true);
  assert.equal(tree.T.get("dir:src/shop").isTest, false);
});

test("level links are summed between the blocks on screen", () => {
  const { ix, tree } = setup();
  const root = levelLinks(ix, tree, "root").map((l) => `${l.source}>${l.target}:${l.count}`).sort();
  assert.deepEqual(root, ["dir:src/shop>db:1", "dir:tests>dir:src/shop:1", "file:src/api.py>dir:src/shop:1"]);
});

test("a block's dependencies: siblings by name, others by their top-level module (@)", () => {
  const { ix, tree } = setup();
  const d = blockDeps(ix, tree, "dir:src/shop", "file:src/shop/cart.py");
  assert.deepEqual(d.out, [
    ["file:src/shop/tax.py", 1],
    ["@db", 1],
  ]);
  assert.deepEqual(d.in.map(([k]) => k).sort(), ["@dir:tests", "@file:src/api.py"]);
});

test("block size follows the number of functions", () => {
  const { tree } = setup();
  const L = layoutLevel(tree.T.get("root"));
  const shop = L.rects.get("dir:src/shop"); // 2 functions
  const api = L.rects.get("file:src/api.py"); // 1 function
  assert.ok(shop.h > api.h);
  assert.ok((shop.x1 - shop.x0) * (shop.y1 - shop.y0) > (api.x1 - api.x0) * (api.y1 - api.y0));
});

test("level layout: one block per child; one-function blocks fall back to lines; deterministic", () => {
  const { tree } = setup();
  const L = layoutLevel(tree.T.get("dir:src/shop"));
  assert.equal(L.blocks.length, 2);
  const cart = L.rects.get("file:src/shop/cart.py");
  const tax = L.rects.get("file:src/shop/tax.py");
  assert.ok(cart.h > tax.h);
  assert.ok(cart.x1 - cart.x0 > 0 && cart.y1 - cart.y0 > 0);
  const again = layoutLevel(tree.T.get("dir:src/shop"));
  assert.deepEqual(
    again.blocks.map((b) => [b.id, b.x0, b.y0]),
    L.blocks.map((b) => [b.id, b.x0, b.y0]),
  );
  assert.equal(layoutLevel(tree.T.get("py:src.shop.tax.rate")).blocks.length, 0);
});

test("roof tiles divide a block's top into its children, inside the block", () => {
  const { tree } = setup();
  const L = layoutLevel(tree.T.get("root"));
  const shop = L.rects.get("dir:src/shop");
  const tiles = roofTiles(shop);
  assert.deepEqual(tiles.map((t) => t.id).sort(), ["file:src/shop/cart.py", "file:src/shop/tax.py"]);
  for (const t of tiles) {
    assert.ok(t.x0 >= shop.x0 && t.x1 <= shop.x1 && t.y0 >= shop.y0 && t.y1 <= shop.y1, t.id);
    assert.equal(t.z, shop.h);
    assert.equal(t.parent, "dir:src/shop");
  }
  assert.deepEqual(roofTiles(L.rects.get("file:src/api.py")).length, 2); // a function and an endpoint
  assert.deepEqual(roofTiles({ ...shop, t: { ...shop.t, children: [shop.t.children[0]] } }), []); // one child: nothing to divide
});

test("change marks: changed blocks and every block containing them; affected ones too", () => {
  const { tree } = setup();
  const marks = changeMarks(tree, {
    changed: { "py:src.shop.tax.rate": "modified" },
    upstream: { "py:src.shop.cart.Cart.total": 1, "py:src.api.get_total": 2 },
    downstream: {},
  });
  assert.equal(marks.get("py:src.shop.tax.rate"), "changed");
  assert.equal(marks.get("file:src/shop/tax.py"), "changed");
  assert.equal(marks.get("dir:src/shop"), "changed"); // contains a change: changed wins over affected
  assert.equal(marks.get("file:src/shop/cart.py"), "affected");
  assert.equal(marks.get("file:src/api.py"), "affected");
  assert.equal(marks.get("dir:tests"), undefined);
});

test("change marks: moved is its own mark, weaker than changed, stronger than affected", () => {
  const { tree } = setup();
  const marks = changeMarks(tree, {
    changed: { "file:src/shop/tax.py": "moved", "py:src.shop.tax.rate": "moved", "py:src.shop.cart.Cart.total": "modified" },
    upstream: { "py:src.shop.tax.rate": 1 },
    downstream: {},
  });
  assert.equal(marks.get("file:src/shop/tax.py"), "moved");
  assert.equal(marks.get("file:src/shop/cart.py"), "changed");
  assert.equal(marks.get("dir:src/shop"), "changed");
});

// Cameras: 2D flat map and the 2.5D city (tilted orthographic orbit view, as in PR World v5).
// The app keeps the camera in LAYOUT coordinates (y grows downwards). deck.gl's orbit view has y
// pointing up, so y is negated when talking to it.
import { OrbitView, OrthographicView } from "@deck.gl/core";
import { fit } from "./layout.js";

export const VIEW_2D = new OrthographicView({ id: "map", flipY: true });
export const VIEW_3D = new OrbitView({ id: "map", orbitAxis: "Z", orthographic: true });
export const PITCH = 35;
export const ORBIT = -30;
const LIMITS = { minZoom: -4, maxZoom: 10 };

export function toDeck(vs, is3d) {
  const [tx, ty, tz = 0] = vs.target;
  return is3d
    ? { ...vs, ...LIMITS, target: [tx, -ty, tz], rotationX: vs.rotationX ?? PITCH, rotationOrbit: vs.rotationOrbit ?? ORBIT }
    : { ...vs, ...LIMITS, target: [tx, ty, 0] };
}

export function fromDeck(v, is3d, prev) {
  return {
    target: is3d ? [v.target[0], -v.target[1], v.target[2] || 0] : [v.target[0], v.target[1], 0],
    zoom: v.zoom,
    rotationX: is3d ? v.rotationX : prev?.rotationX,
    rotationOrbit: is3d ? v.rotationOrbit : prev?.rotationOrbit,
  };
}

export function makeViewport(vs, is3d, size) {
  return (is3d ? VIEW_3D : VIEW_2D).makeViewport({ width: size.width, height: size.height, viewState: toDeck(vs, is3d) });
}

// Camera that frames box r (with its towers, up to r.zTop) in the current view mode.
export function fitView(r, size, is3d, prev, margin = 1.12) {
  if (!is3d) return fit(r, size.width, size.height, margin);
  const base = {
    target: [(r.x0 + r.x1) / 2, (r.y0 + r.y1) / 2, 0],
    zoom: 0,
    rotationX: prev?.rotationX ?? PITCH,
    rotationOrbit: prev?.rotationOrbit ?? ORBIT,
  };
  const vp = makeViewport(base, true, size);
  const top = r.zTop ?? 0;
  const xs = [];
  const ys = [];
  for (const [x, y] of [
    [r.x0, r.y0],
    [r.x1, r.y0],
    [r.x1, r.y1],
    [r.x0, r.y1],
  ])
    for (const z of [0, top]) {
      const [px, py] = vp.project([x, -y, z]);
      xs.push(px);
      ys.push(py);
    }
  const bw = Math.max(1, Math.max(...xs) - Math.min(...xs));
  const bh = Math.max(1, Math.max(...ys) - Math.min(...ys));
  const zoom = Math.max(-4, Math.min(9, Math.log2(Math.min(size.width / (bw * margin), size.height / (bh * margin)))));
  // aim at the point under the centre of the projected box
  const mid = vp.unproject([(Math.min(...xs) + Math.max(...xs)) / 2, (Math.min(...ys) + Math.max(...ys)) / 2], { targetZ: 0 });
  return { ...base, target: [mid[0], -mid[1], 0], zoom };
}
